// Generated by scripts/build_offline.mjs. Edit src modules instead.
'use strict';
const normalize = (value) => String(value ?? '').trim().toLocaleLowerCase('en-US');

/** Align typed characters with the reference. Missing reference characters render as `_`. */
function checkAnswer(expected, actual) {
  const reference = String(expected ?? '').trim();
  const entered = String(actual ?? '').trim();
  const a = [...reference];
  const b = [...entered];
  const rows = a.length + 1;
  const cols = b.length + 1;
  const cost = Array.from({ length: rows }, () => Array(cols).fill(0));
  for (let i = a.length; i >= 0; i--) cost[i][b.length] = a.length - i;
  for (let j = b.length; j >= 0; j--) cost[a.length][j] = b.length - j;

  for (let i = a.length - 1; i >= 0; i--) {
    for (let j = b.length - 1; j >= 0; j--) {
      const same = a[i].toLocaleLowerCase('en-US') === b[j].toLocaleLowerCase('en-US');
      cost[i][j] = Math.min(
        cost[i + 1][j + 1] + (same ? 0 : 1), // match or substitution
        cost[i + 1][j] + 1, // missing reference character
        cost[i][j + 1] + 1, // extra typed character
      );
    }
  }

  const tokens = [];
  let i = 0;
  let j = 0;
  while (i < a.length || j < b.length) {
    if (i < a.length && j < b.length) {
      const same = a[i].toLocaleLowerCase('en-US') === b[j].toLocaleLowerCase('en-US');
      const diagonal = cost[i + 1][j + 1] + (same ? 0 : 1);
      if (diagonal === cost[i][j]) {
        tokens.push({ value: b[j], status: same ? 'correct' : 'incorrect', expected: a[i] });
        i++;
        j++;
        continue;
      }
    }

    // On ties, preserve the earliest possible character matches and mark omissions in place.
    if (i < a.length && cost[i + 1][j] + 1 === cost[i][j]) {
      tokens.push({ value: '_', status: 'missing', expected: a[i] });
      i++;
      continue;
    }

    tokens.push({ value: b[j], status: 'incorrect', expected: '' });
    j++;
  }
  return {
    correct: normalize(reference) === normalize(entered),
    tokens,
  };
}

function createSession(questions, saved = null) {
  const items = Object.fromEntries(questions.map(({ id }) => [id, {
    answer: '', status: 'unanswered', tokens: [],
  }]));
  if (saved?.items) {
    for (const [id, value] of Object.entries(saved.items)) {
      if (items[id]) items[id] = { ...items[id], ...value };
    }
  }
  return {
    index: Math.min(Math.max(0, saved?.index ?? 0), Math.max(0, questions.length - 1)),
    items,
    complete: Boolean(saved?.complete),
  };
}

function submitAnswer(session, answer, questions) {
  const question = questions[session.index];
  if (!question) return session;
  const previous = session.items[question.id];

  if (previous.status === 'correct' && previous.answer === answer) {
    if (session.index === questions.length - 1) return { ...session, complete: true };
    return { ...session, index: session.index + 1, complete: false };
  }

  const result = checkAnswer(question.english, answer);
  return {
    ...session,
    complete: false,
    items: {
      ...session.items,
      [question.id]: {
        answer,
        status: result.correct ? 'correct' : 'incorrect',
        tokens: result.tokens,
      },
    },
  };
}

function updateAnswer(session, answer, questions) {
  const question = questions[session.index];
  if (!question) return session;
  const previous = session.items[question.id];
  if (previous.answer === answer) return session;
  return {
    ...session,
    complete: false,
    items: {
      ...session.items,
      [question.id]: { answer, status: 'unanswered', tokens: [] },
    },
  };
}

function goPrevious(session) {
  if (session.index === 0) return session;
  return { ...session, index: session.index - 1, complete: false };
}

function goToQuestion(session, index, questions) {
  if (!Number.isInteger(index) || index < 0 || index >= questions.length || index === session.index) return session;
  return { ...session, index, complete: false };
}

const VOICE_AUDIO_FOLDERS = Object.freeze({
  am_echo: 'echo',
});

function normalizeVoiceId(voiceId) {
  return Object.hasOwn(VOICE_AUDIO_FOLDERS, voiceId) ? voiceId : 'am_echo';
}

function getVoiceAudioPath(questionId, voiceId = 'am_echo') {
  const folder = VOICE_AUDIO_FOLDERS[normalizeVoiceId(voiceId)];
  return `output/audio/${folder}/${encodeURIComponent(questionId)}.wav`;
}

const SESSION_KEY = 'sentence-trainer-session-v1';
const SETTINGS_KEY = 'sentence-trainer-speech-v1';
const HIDDEN_KEY = 'sentence-trainer-hidden-v1';
const quiz = document.querySelector('#quiz');
const questionCurrent = document.querySelector('#question-current');
const questionTotal = document.querySelector('#question-total');
const catalogButton = document.querySelector('#open-catalog');
const questionCatalog = document.querySelector('#question-catalog');
const catalogGrid = document.querySelector('#catalog-grid');
const chinese = document.querySelector('#chinese-sentence');
const referenceBlock = document.querySelector('#reference-block');
const referenceText = document.querySelector('#reference-text');
const answerInput = document.querySelector('#answer-input');
const answerRender = document.querySelector('#answer-render');
const toolbar = document.querySelector('#keyboard-toolbar');
const message = document.querySelector('#live-message');
const submitButton = document.querySelector('#submit-answer');
const playButton = document.querySelector('#play-button');
const toggleButton = document.querySelector('#toggle-answer');
const eyeIcon = document.querySelector('#eye-icon');
const wordCard = document.querySelector('#word-card');
const wordCardTitle = document.querySelector('#word-card-title');
const wordCardPhonetic = document.querySelector('#word-card-phonetic');
const wordCardSenses = document.querySelector('#word-card-senses');
const eyeOpenMarkup = '<path d="M2.5 12s3.4-6 9.5-6 9.5 6 9.5 6-3.4 6-9.5 6-9.5-6-9.5-6Z"/><circle cx="12" cy="12" r="2.6"/>';
const eyeClosedMarkup = '<path d="M3 3l18 18M10.6 6.2A10.7 10.7 0 0 1 12 6c6.1 0 9.5 6 9.5 6a14.3 14.3 0 0 1-3 3.5M6.1 6.6C3.7 8.3 2.5 12 2.5 12s3.4 6 9.5 6c1.1 0 2.1-.2 3-.5"/><path d="M9.9 9.9a3 3 0 0 0 4.2 4.2"/>';

let questions = [];
let session;
let hiddenById = {};
let editing = false;
let submitLocked = false;
let speechRun = 0;
let speechTimer;
let sentenceAudio;
let swipeStart = null;
let swipeFinishedAt = 0;
let dictionary = {};
let wordPress = null;
let wordPressTimer;
let longPressOpened = false;
let suppressSentenceClickUntil = 0;
let wordCardAnchor = null;

function readStorage(key, fallback) {
  try {
    const raw = localStorage.getItem(key);
    return raw ? JSON.parse(raw) : fallback;
  } catch {
    return fallback;
  }
}

function persist() {
  try {
    localStorage.setItem(SESSION_KEY, JSON.stringify(session));
    localStorage.setItem(HIDDEN_KEY, JSON.stringify(hiddenById));
  } catch {
    showMessage('浏览器无法保存学习进度。');
  }
}

function showMessage(text) {
  message.textContent = text;
  clearTimeout(showMessage.timer);
  showMessage.timer = setTimeout(() => { message.textContent = ''; }, 3200);
}

function currentQuestion() {
  return questions[session.index];
}

function renderAnswer(item) {
  answerRender.replaceChildren();
  if (!item?.answer) return;
  const tokens = item.tokens?.length
    ? item.tokens
    : [...item.answer].map((value) => ({ value, status: 'plain' }));
  const fragment = document.createDocumentFragment();
  for (const token of tokens) {
    const span = document.createElement('span');
    span.className = token.status;
    span.textContent = token.value;
    fragment.append(span);
  }
  answerRender.append(fragment);
}

function resizeAnswer() {
  answerInput.style.height = 'auto';
  const height = Math.max(180, answerInput.scrollHeight);
  answerInput.style.height = `${height}px`;
  answerRender.style.height = `${height}px`;
  answerRender.scrollTop = answerInput.scrollTop;
}

function renderQuestion({ focusInput = false } = {}) {
  const question = currentQuestion();
  if (!question) return;
  closeWordCard();
  const progress = session.index + 1;
  questionCurrent.textContent = String(progress).padStart(2, '0');
  questionTotal.textContent = String(questions.length).padStart(2, '0');
  renderCatalog();
  const item = session.items[question.id];
  chinese.textContent = question.chinese;
  renderReferenceSentence(question.english);
  referenceText.classList.toggle('is-hidden', Boolean(hiddenById[question.id]));
  toggleButton.setAttribute('aria-pressed', String(Boolean(hiddenById[question.id])));
  toggleButton.setAttribute('aria-label', hiddenById[question.id] ? '显示英文答案' : '隐藏英文答案');
  eyeIcon.innerHTML = hiddenById[question.id] ? eyeClosedMarkup : eyeOpenMarkup;
  answerInput.value = item.answer;
  renderAnswer(item);
  resizeAnswer();
  if (session.complete) showMessage('已完成全部例句。');
  if (focusInput) answerInput.focus({ preventScroll: true });
  persist();
}

function renderReferenceSentence(sentence) {
  referenceText.replaceChildren();
  const pattern = /[A-Za-z]+(?:[’'][A-Za-z]+)*(?:-[A-Za-z]+(?:[’'][A-Za-z]+)*)*/g;
  let cursor = 0;
  for (const match of sentence.matchAll(pattern)) {
    const start = match.index;
    if (start > cursor) referenceText.append(document.createTextNode(sentence.slice(cursor, start)));
    const word = document.createElement('span');
    word.className = 'dictionary-word';
    word.textContent = match[0];
    word.dataset.word = match[0];
    referenceText.append(word);
    cursor = start + match[0].length;
  }
  if (cursor < sentence.length) referenceText.append(document.createTextNode(sentence.slice(cursor)));
}

function lookupWord(word) {
  const key = word.toLocaleLowerCase('en-US').replace(/’/g, "'");
  const entries = dictionary.words || dictionary;
  return entries[key] || (key.endsWith("'s") && entries[key.slice(0, -2)]) || (key.endsWith("'") && entries[key.slice(0, -1)]) || null;
}

function positionWordCard(anchor) {
  if (wordCard.hidden || !anchor) return;
  const rect = anchor.getBoundingClientRect();
  if (window.matchMedia('(max-width: 520px)').matches) {
    wordCard.classList.add('is-mobile-sheet');
    const viewport = window.visualViewport;
    const keyboardInset = viewport ? Math.max(0, window.innerHeight - viewport.height - viewport.offsetTop) : 0;
    const toolbarSpace = toolbar.hidden ? 0 : toolbar.offsetHeight;
    wordCard.style.bottom = `${keyboardInset + toolbarSpace + 12}px`;
    wordCard.style.left = '';
    wordCard.style.top = '';
    return;
  }
  wordCard.classList.remove('is-mobile-sheet');
  wordCard.style.bottom = '';
  const card = wordCard.getBoundingClientRect();
  const left = Math.min(Math.max(12, rect.left), window.innerWidth - card.width - 12);
  let top = rect.bottom + 10;
  if (top + card.height > window.innerHeight - 12) top = rect.top - card.height - 10;
  top = Math.max(12, Math.min(top, window.innerHeight - card.height - 12));
  wordCard.style.left = `${left}px`;
  wordCard.style.top = `${top}px`;
}

function showWordCard(wordElement) {
  const selectedWord = wordElement.dataset.word || wordElement.textContent;
  const entry = lookupWord(selectedWord);
  wordCardAnchor = wordElement;
  wordCardTitle.textContent = selectedWord;
  wordCardPhonetic.textContent = entry?.phonetic || '';
  wordCardSenses.replaceChildren();
  if (entry?.senses?.length) {
    for (const sense of entry.senses) {
      const row = document.createElement('div');
      row.className = 'word-card-sense';
      const pos = document.createElement('span');
      pos.className = 'word-card-pos';
      pos.textContent = sense.pos;
      const meaning = document.createElement('span');
      meaning.className = 'word-card-meaning';
      meaning.textContent = sense.meaning;
      row.append(pos, meaning);
      wordCardSenses.append(row);
    }
  } else {
    const fallback = document.createElement('p');
    fallback.className = 'word-card-empty';
    fallback.textContent = '暂未收录这个词的释义。';
    wordCardSenses.append(fallback);
  }
  wordCard.hidden = false;
  positionWordCard(wordElement);
}

function closeWordCard() {
  if (!wordCard) return;
  wordCard.hidden = true;
  wordCardAnchor = null;
}

function cancelWordPress({ closeCard = false } = {}) {
  clearTimeout(wordPressTimer);
  wordPressTimer = null;
  wordPress = null;
  if (closeCard && longPressOpened) closeWordCard();
  longPressOpened = false;
}

function startWordPress(event) {
  if (!event.isPrimary || (event.pointerType === 'mouse' && event.button !== 0) || referenceText.classList.contains('is-hidden')) return;
  const word = event.target.closest('.dictionary-word');
  if (!word) return;
  closeWordCard();
  cancelWordPress();
  wordPress = { id: event.pointerId, x: event.clientX, y: event.clientY, target: word };
  wordPressTimer = setTimeout(() => {
    if (!wordPress || !wordPress.target.isConnected) return;
    longPressOpened = true;
    showWordCard(wordPress.target);
  }, 520);
}

function moveWordPress(event) {
  if (!wordPress || event.pointerId !== wordPress.id) return;
  if (Math.hypot(event.clientX - wordPress.x, event.clientY - wordPress.y) > 12) cancelWordPress({ closeCard: true });
}

function endWordPress(event) {
  if (!wordPress || event.pointerId !== wordPress.id) return;
  const opened = longPressOpened;
  cancelWordPress();
  if (opened) suppressSentenceClickUntil = Date.now() + 600;
}

function renderCatalog() {
  if (!catalogGrid || !session) return;
  catalogGrid.replaceChildren();
  questions.forEach((question, index) => {
    const item = session.items[question.id];
    const state = item.status === 'correct' ? 'correct'
      : item.status === 'incorrect' ? 'incorrect'
        : item.answer ? 'draft' : 'unanswered';
    const button = document.createElement('button');
    button.type = 'button';
    button.className = `catalog-number is-${state}`;
    button.textContent = String(index + 1).padStart(2, '0');
    button.setAttribute('aria-label', `第 ${index + 1} 题，${{ correct: '正确', incorrect: '答错', draft: '有草稿', unanswered: '未作答' }[state]}`);
    if (index === session.index) button.setAttribute('aria-current', 'step');
    button.addEventListener('click', () => {
      const previousIndex = session.index;
      stopSpeech();
      session = goToQuestion(session, index, questions);
      if (session.index !== previousIndex) hiddenById[question.id] = false;
      questionCatalog.close();
      setEditing(false);
      answerInput.blur();
      renderQuestion();
    });
    catalogGrid.append(button);
  });
}

function setEditing(value) {
  editing = value;
  toolbar.hidden = !value;
  document.body.classList.toggle('input-mode', value);
  updateToolbarPosition();
  if (value) {
    setTimeout(() => answerInput.scrollIntoView({ block: 'center', behavior: 'smooth' }), 320);
  }
}

function updateToolbarPosition() {
  const viewport = window.visualViewport;
  if (!viewport || toolbar.hidden) return;
  const bottomGap = Math.max(0, window.innerHeight - viewport.height - viewport.offsetTop);
  toolbar.style.bottom = `${bottomGap}px`;
}

function speechSettings() {
  try {
    return JSON.parse(localStorage.getItem(SETTINGS_KEY) || '{}');
  } catch {
    return {};
  }
}

function stopSpeech() {
  speechRun++;
  clearTimeout(speechTimer);
  if (sentenceAudio) {
    sentenceAudio.pause();
    sentenceAudio.currentTime = 0;
    sentenceAudio = null;
  }
}

function speakQuestion(question, repeatOverride = null) {
  if (!question) return;
  stopSpeech();
  const run = speechRun;
  const settings = speechSettings();
  const voiceId = 'am_echo';
  const repeat = repeatOverride ?? ([1, 2, 3, 5].includes(Number(settings.repeat)) ? Number(settings.repeat) : 1);
  const pause = [0, 1, 2, 3].includes(Number(settings.pause)) ? Number(settings.pause) : 0;
  const rate = Math.min(1.5, Math.max(0.5, Number(settings.rate) || 0.85));
  let played = 0;
  const playNext = () => {
    if (run !== speechRun) return;
    const audio = new Audio(new URL(getVoiceAudioPath(question.id, voiceId), document.baseURI));
    sentenceAudio = audio;
    audio.playbackRate = rate;
    audio.onended = () => {
      played++;
      if (played < repeat && run === speechRun) speechTimer = setTimeout(playNext, pause * 1000);
    };
    audio.onerror = () => {
      if (run === speechRun) showMessage('所选音色的音频播放失败，请检查文件或重新点击播放。');
    };
    audio.play().catch(() => {
      if (run === speechRun) showMessage('所选音色的音频播放失败，请重新点击播放。');
    });
  };
  playNext();
}

function speakCurrent() {
  speakQuestion(currentQuestion());
}

function submitCurrent() {
  if (submitLocked) return;
  submitLocked = true;
  submitButton.disabled = true;
  const submittedQuestion = currentQuestion();
  const beforeIndex = session.index;
  session = submitAnswer(session, answerInput.value, questions);
  if (session.index !== beforeIndex) {
    stopSpeech();
    hiddenById[currentQuestion().id] = false;
    renderQuestion({ focusInput: editing });
  } else {
    const item = session.items[currentQuestion().id];
    renderAnswer(item);
    if (item.status === 'incorrect') {
      referenceBlock.classList.remove('submit-shake');
      void referenceBlock.offsetWidth;
      referenceBlock.classList.add('submit-shake');
    } else if (session.complete) {
      showMessage('已完成全部例句。');
    }
    persist();
  }
  speakQuestion(submittedQuestion, 1);
  setTimeout(() => {
    submitLocked = false;
    submitButton.disabled = false;
  }, 460);
}

function goBack() {
  if (session.index === 0) return;
  stopSpeech();
  session = goPrevious(session);
  renderQuestion({ focusInput: editing });
}

function hasSelection() {
  return Boolean(window.getSelection?.().toString());
}

function onTouchStart(event) {
  if (event.touches.length !== 1 || editing || hasSelection()) {
    swipeStart = null;
    return;
  }
  const target = event.target;
  if (target.closest('textarea, button, a, input, select, [role="button"]')) {
    swipeStart = null;
    return;
  }
  const touch = event.touches[0];
  swipeStart = { x: touch.clientX, y: touch.clientY, time: Date.now() };
}

function onTouchEnd(event) {
  if (!swipeStart || event.changedTouches.length !== 1 || editing || hasSelection()) {
    swipeStart = null;
    return;
  }
  const touch = event.changedTouches[0];
  const dx = touch.clientX - swipeStart.x;
  const dy = touch.clientY - swipeStart.y;
  const duration = Date.now() - swipeStart.time;
  if (dx > 76 && Math.abs(dx) > Math.abs(dy) * 1.35 && duration < 900) {
    event.preventDefault();
    swipeFinishedAt = Date.now();
    goBack();
  }
  swipeStart = null;
}

async function initialize() {
  try {
    const embeddedBank = document.querySelector('#question-bank-data')?.textContent.trim();
    if (embeddedBank) {
      questions = JSON.parse(embeddedBank);
    } else {
      const response = await fetch('./output/question_bank/questions.json');
      if (!response.ok) throw new Error(`Question bank request failed: ${response.status}`);
      questions = await response.json();
    }
    if (!Array.isArray(questions) || !questions.length) throw new Error('Question bank is empty');
    questions.sort((a, b) => a.order - b.order);
    if (questions.length !== 83 || questions.some((item, index) => item.order !== index + 1 || !item.id || !item.chinese?.trim() || !item.english?.trim())) {
      throw new Error('Question bank does not match the reviewed V1.0 dataset');
    }
    const embeddedDictionary = document.querySelector('#dictionary-data')?.textContent.trim();
    if (!embeddedDictionary) throw new Error('Embedded word dictionary is missing');
    dictionary = JSON.parse(embeddedDictionary);
    const saved = readStorage(SESSION_KEY, null);
    session = createSession(questions, saved);
    hiddenById = readStorage(HIDDEN_KEY, {});
    renderQuestion();
  } catch (error) {
    console.error(error);
    chinese.textContent = '题库读取失败，请确认通过本地服务器打开应用。';
    answerInput.disabled = true;
  }
}

answerInput.addEventListener('focus', () => setEditing(true));
answerInput.addEventListener('input', () => {
  session = updateAnswer(session, answerInput.value, questions);
  renderAnswer(session.items[currentQuestion().id]);
  resizeAnswer();
  persist();
});
answerInput.addEventListener('scroll', () => { answerRender.scrollTop = answerInput.scrollTop; });
answerInput.addEventListener('keydown', (event) => {
  // Enter is intentionally left to the textarea so it always inserts a line break.
  if (event.key === 'Enter') event.stopPropagation();
});

document.querySelector('#exit-input').addEventListener('click', () => {
  setEditing(false);
  answerInput.blur();
});
toolbar.addEventListener('pointerdown', (event) => {
  const button = event.target.closest('button');
  if (button && button.id !== 'exit-input') event.preventDefault();
});
submitButton.addEventListener('click', submitCurrent);
catalogButton.addEventListener('click', () => {
  setEditing(false);
  answerInput.blur();
  questionCatalog.showModal();
});
document.querySelector('#close-catalog').addEventListener('click', () => questionCatalog.close());
questionCatalog.addEventListener('click', (event) => {
  if (event.target === questionCatalog) questionCatalog.close();
});
playButton.addEventListener('click', speakCurrent);
referenceText.addEventListener('pointerdown', startWordPress);
document.addEventListener('pointermove', moveWordPress);
document.addEventListener('pointerup', endWordPress);
document.addEventListener('pointercancel', endWordPress);
referenceText.addEventListener('contextmenu', (event) => {
  if (longPressOpened) event.preventDefault();
});
referenceText.addEventListener('click', (event) => {
  if (Date.now() < suppressSentenceClickUntil && event.detail !== 0) {
    event.preventDefault();
    event.stopPropagation();
    suppressSentenceClickUntil = 0;
    return;
  }
  speakCurrent();
});
referenceText.addEventListener('keydown', (event) => {
  if (event.key === 'Enter' || event.key === ' ') {
    event.preventDefault();
    speakCurrent();
  }
});
document.querySelector('#close-word-card').addEventListener('click', closeWordCard);
document.addEventListener('click', (event) => {
  if (!wordCard.hidden && !wordCard.contains(event.target) && !referenceText.contains(event.target)) closeWordCard();
});
document.addEventListener('keydown', (event) => {
  if (event.key === 'Escape' && !wordCard.hidden) closeWordCard();
});
window.visualViewport?.addEventListener('resize', () => positionWordCard(wordCardAnchor));
window.visualViewport?.addEventListener('scroll', () => positionWordCard(wordCardAnchor));
window.addEventListener('resize', () => positionWordCard(wordCardAnchor));
toggleButton.addEventListener('click', () => {
  closeWordCard();
  const id = currentQuestion().id;
  hiddenById[id] = !hiddenById[id];
  renderQuestion();
});

quiz.addEventListener('click', (event) => {
  if (Date.now() - swipeFinishedAt < 500 || hasSelection()) return;
  if (event.target === quiz || event.target.classList.contains('sentence-block')) speakCurrent();
});
quiz.addEventListener('touchstart', onTouchStart, { passive: true });
quiz.addEventListener('touchend', onTouchEnd, { passive: false });
quiz.addEventListener('touchcancel', () => { swipeStart = null; }, { passive: true });
window.visualViewport?.addEventListener('resize', updateToolbarPosition);
window.visualViewport?.addEventListener('scroll', updateToolbarPosition);
window.addEventListener('resize', updateToolbarPosition);
document.addEventListener('visibilitychange', () => { if (document.hidden) stopSpeech(); });

initialize();
